package com.sirithree.shopops.admin.benchmark.v1.dataset.stage7b; import static org.assertj.core.api.Assertions.assertThat; import org.junit.jupiter.api.Test; import java.util.Map;
class GovernanceScaleupManifestTest { @Test void manifestFreezesCandidateWithoutFormalRun() throws Exception { Map<String,Object>d=Stage7BGovernanceDatasetSupport.objectResource("/benchmark/v1/benchmark-governance-stage7b-scaleup-candidate-manifest.json"); assertThat(d.get("status")).isEqualTo("EXPANSION_CANDIDATE"); assertThat(d.get("caseCount")).isEqualTo(106); assertThat(d.get("semanticRootCount")).isEqualTo(96); assertThat(d.get("testRootCount")).isEqualTo(54); assertThat(d.get("formalRunOccurred")).isEqualTo(false); assertThat(d.get("heldOutExecutionOccurred")).isEqualTo(false); }}
